import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/utils";

export type TableToolbarProps = Omit<ComponentProps<"div">, "title"> & {
  title?: ReactNode;
  titleId?: string;
  description?: ReactNode;
  descriptionId?: string;
  count?: ReactNode;
  search?: ReactNode;
  actions?: ReactNode;
  selection?: ReactNode;
};

export function TableToolbar({
  title,
  titleId,
  description,
  descriptionId,
  count,
  search,
  actions,
  selection,
  children,
  className,
  ...props
}: TableToolbarProps) {
  return (
    <div
      data-slot="table-toolbar"
      className={cn(
        "grid gap-4 border-b border-border px-4 py-4 sm:px-6",
        className,
      )}
      {...props}
    >
      {(title || description) && (
        <div className="min-w-0">
          {title && (
            <div className="flex flex-wrap items-center gap-2.5">
              <h2
                id={titleId}
                className="text-base leading-6 font-semibold tracking-tight"
              >
                {title}
              </h2>
              {count != null && (
                <span className="rounded-full border border-primary/20 bg-accent/65 px-2.5 py-0.5 text-xs font-medium text-foreground tabular-nums">
                  {count}
                </span>
              )}
            </div>
          )}
          {description && (
            <p
              id={descriptionId}
              className="mt-1 text-[13px] leading-6 text-muted-foreground"
            >
              {description}
            </p>
          )}
        </div>
      )}
      {(search || actions || children) && (
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          {search}
          {(actions || children) && (
            <div
              data-slot="table-toolbar-actions"
              className="flex flex-wrap items-center gap-2 sm:ml-auto"
            >
              {actions}
              {children}
            </div>
          )}
        </div>
      )}
      {selection && (
        <div
          data-slot="table-selection-toolbar"
          className="flex flex-wrap items-center justify-between gap-3 rounded-[var(--radius-md,10px)] border border-primary/20 bg-accent/50 px-3 py-2.5"
        >
          {selection}
        </div>
      )}
    </div>
  );
}

import type { IntegrationRecord } from "@/lib/integrations/contracts";

export type OperationalEmailProvider =
  "resend" | "postmark" | "sendgrid" | "ses";
export type OperationalEmailEventContext = {
  /** An authorized, tenant-scoped event/recipient ID chosen by the backend. */
  id: string;
  name: string;
  /** Provider event time, supplied after backend verification/reconciliation. */
  updatedAt: string;
  description?: string;
  recipient?: string;
};

const statuses: Record<string, readonly [string, string]> = {
  queued: ["Queued", "En cola"],
  sent: ["Sent", "Enviado"],
  delivered: ["Delivered", "Entregado"],
  failed: ["Failed", "Falló"],
  rejected: ["Rejected", "Rechazado"],
  bounced: ["Bounced", "Rebotado"],
};

export function operationalEmailStatus(status: string) {
  const known = Object.hasOwn(statuses, status);
  return {
    label: known ? statuses[status] : ([status, status] as const),
    variant: (["failed", "rejected", "bounced"].includes(status)
      ? "destructive"
      : status === "queued"
        ? "warning"
        : "neutral") as "destructive" | "warning" | "neutral",
    known,
  };
}

function object(value: unknown): Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function own(value: Record<string, unknown>, key: string) {
  return Object.hasOwn(value, key) ? value[key] : undefined;
}

function boundedText(value: unknown, max: number): string | null {
  return typeof value === "string" &&
    value.length > 0 &&
    value.length <= max &&
    !/[\u0000-\u001f\u007f]/.test(value)
    ? value
    : null;
}

export function reportedEmailDetails(delivery: {
  status: string;
  reasonCode?: unknown;
  disposition?: unknown;
  occurredAt?: unknown;
}) {
  const occurredAt = boundedText(delivery.occurredAt, 100);
  return {
    reasonCode: boundedText(delivery.reasonCode, 300),
    disposition: boundedText(delivery.disposition, 300),
    occurredAt:
      occurredAt && Number.isFinite(Date.parse(occurredAt)) ? occurredAt : null,
  };
}

const nativeStatuses: Record<
  OperationalEmailProvider,
  Record<string, string>
> = {
  resend: {
    "email.scheduled": "queued",
    "email.sent": "sent",
    "email.delivered": "delivered",
    "email.failed": "failed",
    "email.bounced": "bounced",
    "email.suppressed": "rejected",
  },
  postmark: {
    Delivery: "delivered",
    Bounce: "bounced",
  },
  sendgrid: {
    processed: "queued",
    delivered: "delivered",
    bounce: "bounced",
    dropped: "rejected",
  },
  ses: {
    Send: "sent",
    Delivery: "delivered",
    Bounce: "bounced",
    Reject: "rejected",
    "Rendering Failure": "failed",
  },
};

/**
 * Pure DTO mapping for an already verified/unwrapped provider event.
 * It is not a webhook verifier, SDK transport or delivery-state reducer.
 * Unknown event types remain records with their exact reported status.
 */
export function mapOperationalEmailEvent(
  provider: OperationalEmailProvider,
  payload: unknown,
  context: OperationalEmailEventContext,
): IntegrationRecord {
  if (!Object.hasOwn(nativeStatuses, provider))
    throw new TypeError("Unsupported email event provider.");
  const event = object(payload);
  const data = object(own(event, "data"));
  const nativeEvent = boundedText(
    provider === "resend"
      ? own(event, "type")
      : provider === "postmark"
        ? own(event, "RecordType")
        : provider === "sendgrid"
          ? own(event, "event")
          : (own(event, "eventType") ?? own(event, "notificationType")),
    100,
  );
  if (!nativeEvent)
    throw new TypeError("A bounded native email event type is required.");
  const mapping = nativeStatuses[provider];
  let status = Object.hasOwn(mapping, nativeEvent)
    ? mapping[nativeEvent]
    : nativeEvent;
  let reasonCode: unknown;
  let disposition: unknown;
  if (provider === "resend") {
    const bounce = object(own(data, "bounce"));
    const suppressed = object(own(data, "suppressed"));
    reasonCode =
      nativeEvent === "email.bounced"
        ? own(bounce, "subType")
        : nativeEvent === "email.suppressed"
          ? own(suppressed, "type")
          : undefined;
    disposition = own(bounce, "type");
  } else if (provider === "postmark") {
    disposition = own(event, "Type");
    const code = own(event, "TypeCode");
    if (typeof code === "number" && Number.isSafeInteger(code) && code >= 0)
      reasonCode = String(code);
    if (nativeEvent === "Bounce" && disposition === "SMTPApiError")
      status = "rejected";
  } else if (provider === "sendgrid") {
    // SMTP status is a code; free-form reason/response, headers, IPs, custom
    // arguments and email content are intentionally not copied into the DTO.
    reasonCode = own(event, "status");
    disposition = own(event, "type");
  } else {
    const bounce = object(own(event, "bounce"));
    reasonCode =
      nativeEvent === "Reject"
        ? own(object(own(event, "reject")), "reason")
        : own(bounce, "bounceSubType");
    disposition = own(bounce, "bounceType");
  }
  const details = reportedEmailDetails({ status, reasonCode, disposition });
  const id = boundedText(context.id, 200);
  const name = boundedText(context.name, 300);
  const updatedAt = boundedText(context.updatedAt, 100);
  if (
    !id ||
    !name ||
    !updatedAt ||
    !Number.isFinite(Date.parse(updatedAt)) ||
    (context.description !== undefined &&
      (typeof context.description !== "string" ||
        context.description.length > 2000)) ||
    (context.recipient !== undefined && !boundedText(context.recipient, 500))
  )
    throw new TypeError(
      "A bounded, authorized email event context is required.",
    );
  return {
    id,
    name,
    type: "email-delivery",
    status,
    updatedAt,
    description: context.description ?? "",
    fields: {
      provider,
      nativeEvent,
      ...(context.recipient ? { recipient: context.recipient } : {}),
      ...(details.reasonCode ? { reasonCode: details.reasonCode } : {}),
      ...(details.disposition ? { disposition: details.disposition } : {}),
    },
  };
}

"use client";

import {
  createContext,
  useContext,
  useId,
  useState,
  type ReactNode,
} from "react";
import { Check, CircleAlert, RefreshCw, X } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Field } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { Spinner } from "@/components/ui/spinner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogTitle,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";
import type {
  IntegrationAction,
  IntegrationValues,
} from "@/lib/integrations/contracts";
import {
  operationalSensitiveField,
  operationalPermitted,
  operationalText,
  validateOperationalValues,
  type OperationalFieldError,
} from "./operational-model";
import type { OperationalSession } from "./operational-session";

const permissionContext = createContext<readonly string[] | null>(null);

export function OperationalPermissionsProvider({
  permissions,
  children,
}: {
  permissions: readonly string[];
  children: ReactNode;
}) {
  return (
    <permissionContext.Provider value={permissions}>
      {children}
    </permissionContext.Provider>
  );
}

export function OperationalPermissionNote({
  action,
}: {
  action: IntegrationAction | null;
}) {
  const { l } = useLanguage();
  const permissions = useContext(permissionContext);
  if (!action || !permissions || operationalPermitted(action, permissions))
    return null;
  return (
    <p
      role="status"
      className="rounded-lg border border-border bg-surface-subtle p-3 text-xs leading-6 text-muted-foreground"
    >
      {l(
        "This connection needs permission for this action. Update its permissions in connection settings.",
        "Esta conexión necesita permiso para esta acción. Actualiza los permisos en sus ajustes de conexión.",
      )}
    </p>
  );
}

export function OperationalPanel({
  title,
  description,
  children,
  className,
  accessory,
}: {
  title: ReactNode;
  description?: ReactNode;
  children: ReactNode;
  className?: string;
  accessory?: ReactNode;
}) {
  const id = useId();
  return (
    <section
      aria-labelledby={id}
      className={cn(
        "min-w-0 rounded-2xl border border-border bg-surface p-4 shadow-sm sm:p-6",
        className,
      )}
    >
      <div className="mb-5 flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0 flex-1">
          <h3 id={id} className="text-sm font-semibold tracking-tight">
            {title}
          </h3>
          {description && (
            <p className="mt-1 text-xs leading-6 text-muted-foreground">
              {description}
            </p>
          )}
        </div>
        {accessory}
      </div>
      {children}
    </section>
  );
}

export function OperationalEmpty({ children }: { children: ReactNode }) {
  return (
    <div className="rounded-xl border border-dashed border-border bg-surface-subtle/50 px-5 py-8 text-center text-xs leading-6 text-muted-foreground">
      {children}
    </div>
  );
}

export function OperationalFields({
  action,
  values,
  onChange,
  disabled,
  errors = {},
  exclude = [],
}: {
  action: IntegrationAction;
  values: IntegrationValues;
  onChange: (values: IntegrationValues) => void;
  disabled?: boolean;
  errors?: Record<string, OperationalFieldError>;
  exclude?: string[];
}) {
  const { l } = useLanguage();
  const prefix = useId();
  const messages: Record<OperationalFieldError, string> = {
    required: l("Complete this field.", "Completa este campo."),
    number: l("Enter a finite number.", "Escribe un número válido."),
    url: l(
      "Use a public HTTPS URL or a relative path.",
      "Usa una URL HTTPS pública o una ruta relativa.",
    ),
    option: l("Choose an available option.", "Elige una opción disponible."),
    json: l("Enter valid JSON.", "Escribe JSON válido."),
  };
  return (
    <div className="grid gap-4 sm:grid-cols-2">
      {action.fields
        .filter((field) => !exclude.includes(field.id))
        .map((field) => {
          const id = `${prefix}-${field.id}`;
          const label = l(field.label.en, field.label.es);
          const value = values[field.id];
          const error = errors[field.id]
            ? messages[errors[field.id]]
            : undefined;
          const description = field.description
            ? l(field.description.en, field.description.es)
            : undefined;
          const change = (next: string | number | boolean) =>
            onChange({ ...values, [field.id]: next });
          if (operationalSensitiveField(field.id)) {
            return (
              <p
                key={field.id}
                className="text-xs leading-6 text-muted-foreground sm:col-span-2"
              >
                {l(
                  "This action requires server configuration. Credentials belong in your backend connection.",
                  "Esta acción requiere configuración del servidor. Las credenciales pertenecen a la conexión de tu backend.",
                )}
              </p>
            );
          }
          const multiline =
            field.type === "text" &&
            /body|content|message|payload|variables|mapping|properties|arguments|cuerpo|contenido/i.test(
              `${field.id} ${field.label.en}`,
            );
          if (field.type === "toggle") {
            return (
              <div key={field.id} className="space-y-1.5">
                <label
                  htmlFor={id}
                  className="flex min-h-11 cursor-pointer items-center justify-between gap-4 rounded-lg border border-border bg-surface-subtle/40 px-3 text-xs font-medium"
                >
                  <span>
                    {label}
                    {field.required ? " *" : ""}
                  </span>
                  <Switch
                    id={id}
                    checked={value === true}
                    onCheckedChange={change}
                    disabled={disabled}
                    aria-describedby={
                      description || error ? `${id}-help` : undefined
                    }
                    aria-invalid={Boolean(error)}
                  />
                </label>
                {(description || error) && (
                  <p
                    id={`${id}-help`}
                    role={error ? "alert" : undefined}
                    className={cn(
                      "text-xs leading-5",
                      error
                        ? "text-destructive-foreground"
                        : "text-muted-foreground",
                    )}
                  >
                    {error ?? description}
                  </p>
                )}
              </div>
            );
          }
          return (
            <Field
              key={field.id}
              htmlFor={id}
              label={`${label}${field.required ? " *" : ""}`}
              description={description}
              error={error}
              className={multiline ? "sm:col-span-2" : undefined}
            >
              {field.type === "select" ? (
                <Select
                  value={typeof value === "string" ? value : ""}
                  options={(field.options ?? []).map((option) => ({
                    value: option.value,
                    label: l(option.label.en, option.label.es),
                  }))}
                  onValueChange={change}
                  disabled={disabled}
                  placeholder={l("Choose…", "Elige…")}
                  aria-label={label}
                />
              ) : multiline ? (
                <Textarea
                  value={typeof value === "string" ? value : ""}
                  onChange={(event) => change(event.target.value)}
                  disabled={disabled}
                  placeholder={field.placeholder}
                  required={field.required}
                  rows={4}
                />
              ) : (
                <Input
                  value={
                    typeof value === "number" || typeof value === "string"
                      ? value
                      : ""
                  }
                  type={
                    field.type === "number"
                      ? "number"
                      : field.type === "url"
                        ? "url"
                        : /recipient|email|(^|[_-])to($|[_-])/i.test(field.id)
                          ? "email"
                          : "text"
                  }
                  step={field.type === "number" ? "any" : undefined}
                  onChange={(event) =>
                    change(
                      field.type === "number" && event.target.value !== ""
                        ? Number(event.target.value)
                        : event.target.value,
                    )
                  }
                  disabled={disabled}
                  placeholder={field.placeholder}
                  required={field.required}
                />
              )}
            </Field>
          );
        })}
    </div>
  );
}

export function OperationalActionForm({
  action,
  values,
  onChange,
  onSubmit,
  disabled,
  pending,
  buttonLabel,
  children,
  exclude = [],
}: {
  action: IntegrationAction | null;
  values: IntegrationValues;
  onChange: (values: IntegrationValues) => void;
  onSubmit: (values: IntegrationValues) => void;
  disabled?: boolean;
  pending?: boolean;
  buttonLabel?: string;
  children?: ReactNode;
  exclude?: string[];
}) {
  const { l } = useLanguage();
  const permissions = useContext(permissionContext);
  const [attempted, setAttempted] = useState(false);
  if (!action) {
    return (
      <OperationalEmpty>
        {l(
          "This connection does not expose this action.",
          "Esta conexión no ofrece esta acción.",
        )}
      </OperationalEmpty>
    );
  }
  const errors = validateOperationalValues(action, values);
  const permitted = !permissions || operationalPermitted(action, permissions);
  return (
    <form
      className="space-y-4"
      noValidate
      onSubmit={(event) => {
        event.preventDefault();
        setAttempted(true);
        if (!Object.keys(errors).length && !disabled && !pending && permitted)
          onSubmit(values);
      }}
    >
      <OperationalFields
        action={action}
        values={values}
        onChange={onChange}
        disabled={pending}
        errors={attempted ? errors : {}}
        exclude={exclude}
      />
      {children}
      <OperationalPermissionNote action={action} />
      <Button
        type="submit"
        disabled={disabled || !permitted}
        loading={pending}
        appearance="gradient"
      >
        {buttonLabel ?? l(action.label.en, action.label.es)}
      </Button>
    </form>
  );
}

export function OperationalFeedback({
  operation,
  label,
}: {
  operation: OperationalSession["read"];
  label?: string;
}) {
  const { l } = useLanguage();
  if (!operation.pending && !operation.error) return null;
  const cancelled = operation.errorCode === "cancelled";
  return (
    <div
      role={operation.error && !cancelled ? "alert" : "status"}
      aria-live="polite"
      className={cn(
        "flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border bg-surface-subtle px-4 py-3",
        operation.error && !cancelled && "border-destructive/30",
      )}
    >
      <div className="min-w-0 flex-1 text-xs leading-6">
        <p className="flex items-center gap-2">
          {operation.pending ? (
            <Spinner
              label={label ?? l("Working", "Procesando")}
              className="size-4"
            />
          ) : (
            <CircleAlert className="size-4 shrink-0" aria-hidden="true" />
          )}
          {operation.error ??
            label ??
            l("Waiting for the backend…", "Esperando al backend…")}
        </p>
        {cancelled && (
          <p className="text-muted-foreground">
            {l(
              "Waiting stopped. Check the backend before repeating a side effect.",
              "Se dejó de esperar. Comprueba el backend antes de repetir una operación con efectos.",
            )}
          </p>
        )}
      </div>
      <Button
        size="sm"
        variant="ghost"
        type="button"
        onClick={operation.pending ? operation.cancel : operation.reset}
      >
        <X aria-hidden="true" />
        {operation.pending
          ? l("Cancel request", "Cancelar solicitud")
          : l("Dismiss", "Cerrar")}
      </Button>
    </div>
  );
}

export function OperationalRefresh({
  session,
  values,
}: {
  session: OperationalSession;
  values?: IntegrationValues;
}) {
  const { l } = useLanguage();
  if (!session.query) return null;
  const input = values ?? session.initialQueryValues;
  const needsInput =
    !values &&
    !session.loaded &&
    Object.keys(validateOperationalValues(session.query, input)).length > 0;
  if (needsInput) return null;
  return (
    <Button
      size="sm"
      variant="outline"
      type="button"
      loading={session.read.pending}
      disabled={!session.can(session.query) || session.write.pending}
      onClick={() => void session.refresh(values ? input : undefined)}
    >
      <RefreshCw aria-hidden="true" />
      {l("Refresh", "Actualizar")}
    </Button>
  );
}

export type OperationalReviewPacket = {
  action: IntegrationAction;
  values: IntegrationValues;
  summary?: { label: string; value: string }[];
  content?: string;
};

export function OperationalReviewDialog({
  packet,
  demo,
  onConfirm,
  onReject,
}: {
  packet: OperationalReviewPacket;
  demo: boolean;
  onConfirm: () => void;
  onReject: () => void;
}) {
  const { l } = useLanguage();
  const checkId = useId();
  const [acknowledged, setAcknowledged] = useState(false);
  const rows =
    packet.summary ??
    packet.action.fields
      .filter(
        (field) =>
          !operationalSensitiveField(field.id) &&
          packet.values[field.id] !== undefined,
      )
      .map((field) => ({
        label: l(field.label.en, field.label.es),
        value: operationalText(packet.values[field.id], 1200),
      }));
  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onReject();
      }}
    >
      <DialogContent
        closeLabel={l("Close review", "Cerrar revisión")}
        className="max-w-2xl"
      >
        <DialogTitle>
          {l("Review before running", "Revisa antes de ejecutar")}
        </DialogTitle>
        <DialogDescription>
          {l(packet.action.label.en, packet.action.label.es)} ·{" "}
          {demo
            ? l(
                "Local demo. No external delivery or trigger.",
                "Demo local. Sin envío ni activación externa.",
              )
            : l(
                "The confirmed values will be sent to your connected backend.",
                "Los valores confirmados se enviarán a tu backend conectado.",
              )}
        </DialogDescription>
        <dl className="mt-5 grid gap-3 rounded-xl border border-border bg-surface-subtle/50 p-4">
          {rows.map((row, index) => (
            <div
              key={`${row.label}-${index}`}
              className="grid gap-1 sm:grid-cols-[9rem_1fr]"
            >
              <dt className="text-xs font-medium text-muted-foreground">
                {row.label}
              </dt>
              <dd className="whitespace-pre-wrap break-words text-xs leading-6">
                {operationalText(row.value, 1800) || l("Empty", "Vacío")}
              </dd>
            </div>
          ))}
        </dl>
        {packet.content && (
          <div className="mt-4 max-h-80 overflow-auto whitespace-pre-wrap break-words rounded-xl border border-border p-4 text-sm leading-7">
            {operationalText(packet.content, 64000)}
          </div>
        )}
        <label
          htmlFor={checkId}
          className="mt-5 flex min-h-11 cursor-pointer items-center gap-3 rounded-lg px-1 text-xs leading-6"
        >
          <Checkbox
            id={checkId}
            checked={acknowledged}
            onCheckedChange={setAcknowledged}
          />
          {l(
            "I reviewed the recipient, resource and content of this action.",
            "Revisé el destinatario, el recurso y el contenido de esta acción.",
          )}
        </label>
        <DialogFooter className="flex-wrap">
          <Button variant="outline" type="button" onClick={onReject}>
            {l("Back to editing", "Volver a editar")}
          </Button>
          <Button type="button" disabled={!acknowledged} onClick={onConfirm}>
            <Check aria-hidden="true" />
            {l("Confirm and run", "Confirmar y ejecutar")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";
import { File, ImagePlus, Mail, Upload, X } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Field } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import {
  initialOperationalValues,
  interpolateOperationalTemplate,
  operationalAction,
  operationalField,
  operationalRasterImage,
  operationalTemplateVariables,
  operationalText,
  operationalUploadLimit,
  operationalValue,
  validOperationalRecipients,
  validateOperationalFile,
  validateOperationalValues,
  withOperationalValue,
} from "./operational-model";
import {
  OperationalEmpty,
  OperationalFields,
  OperationalPanel,
  OperationalPermissionNote,
  OperationalRefresh,
} from "./operational-fields";
import {
  OperationalDate,
  OperationalRecordDetail,
  OperationalRecordTable,
  OperationalUpload,
} from "./operational-results";
import type {
  IntegrationRecord,
  IntegrationResult,
} from "@/lib/integrations/contracts";
import type { OperationalDomainProps } from "./operational-workbench";
import {
  operationalEmailStatus,
  reportedEmailDetails,
} from "./operational-email-events";

export function OperationalFiles({ props, session }: OperationalDomainProps) {
  const { l, number } = useLanguage();
  const id = useId();
  const picker = useRef<HTMLInputElement | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [alt, setAlt] = useState("");
  const [preview, setPreview] = useState<string | null>(null);
  const [attempted, setAttempted] = useState(false);
  const [uploadedFile, setUploadedFile] = useState<File | null>(null);
  const [detail, setDetail] = useState<IntegrationRecord | null>(null);
  useEffect(
    () => () => {
      if (preview) URL.revokeObjectURL(preview);
    },
    [preview],
  );
  const busy = session.write.pending || session.read.pending;
  const uploadAction = operationalAction(props.definition, "upload");
  const canUpload =
    session.connected && (!uploadAction || session.can(uploadAction));
  const error = file ? validateOperationalFile(file, alt) : null;
  const messages = {
    empty: l("Choose a non-empty file.", "Elige un archivo con contenido."),
    size: l(
      "This workbench accepts files up to 20 MB. Your backend may apply a lower limit.",
      "Este workbench acepta archivos de hasta 20 MB. Tu backend puede aplicar un límite menor.",
    ),
    alt: l(
      "Add alternative text for this image.",
      "Añade texto alternativo para esta imagen.",
    ),
  };
  const choose = (next: File | null) => {
    setFile(next);
    setAlt("");
    setAttempted(false);
    setUploadedFile(null);
    setPreview(
      next &&
        next.size <= operationalUploadLimit &&
        operationalRasterImage(next.type)
        ? URL.createObjectURL(next)
        : null,
    );
  };
  return (
    <div className="space-y-5">
      <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
        <OperationalPanel
          title={l("Upload a file", "Subir un archivo")}
          description={l(
            "Review the file and its description before uploading.",
            "Revisa el archivo y su descripción antes de subirlo.",
          )}
        >
          <form
            noValidate
            className="space-y-4"
            onSubmit={(event) => {
              event.preventDefault();
              setAttempted(true);
              if (!file || error || busy || !canUpload || uploadedFile === file)
                return;
              const selected = file;
              void session
                .upload(selected, alt.trim() || undefined)
                .then((result) => {
                  if (result?.kind === "upload") setUploadedFile(selected);
                });
            }}
          >
            <input
              ref={picker}
              id={`${id}-file`}
              type="file"
              className="sr-only"
              tabIndex={-1}
              disabled={busy}
              aria-label={l("Choose file", "Elegir archivo")}
              aria-describedby={`${id}-policy`}
              onChange={(event) => choose(event.target.files?.[0] ?? null)}
            />
            <button
              type="button"
              disabled={busy}
              onClick={() => picker.current?.click()}
              className="group flex min-h-36 w-full flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-primary/35 bg-accent/30 p-5 text-center outline-none transition-colors hover:border-primary/60 hover:bg-accent/60 focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50 motion-reduce:transition-none"
              aria-describedby={`${id}-policy`}
            >
              <Upload className="size-6 text-primary" aria-hidden="true" />
              <span className="text-sm font-semibold">
                {file
                  ? operationalText(file.name, 200)
                  : l("Choose a file", "Elige un archivo")}
              </span>
              <span className="text-xs text-muted-foreground">
                {file
                  ? `${number(file.size / (1024 * 1024), { maximumFractionDigits: 2 })} MB · ${operationalText(file.type || l("Unknown type", "Tipo desconocido"), 100)}`
                  : l(
                      "Images, documents and other files",
                      "Imágenes, documentos y otros archivos",
                    )}
              </span>
            </button>
            <p
              id={`${id}-policy`}
              className="text-[11px] leading-5 text-muted-foreground"
            >
              {l(
                `Workbench limit: ${number(operationalUploadLimit / (1024 * 1024))} MB. Image previews require alternative text.`,
                `Límite del workbench: ${number(operationalUploadLimit / (1024 * 1024))} MB. Las vistas de imágenes requieren texto alternativo.`,
              )}
            </p>
            <Field
              label={l(
                "Alternative text / description",
                "Texto alternativo / descripción",
              )}
              description={l(
                "Describe the image’s content, rather than its filename.",
                "Describe el contenido de la imagen, en lugar de su nombre de archivo.",
              )}
              error={attempted && error ? messages[error] : undefined}
            >
              <Input
                value={alt}
                onChange={(event) => setAlt(event.target.value)}
                disabled={busy || (uploadedFile === file && Boolean(file))}
                maxLength={1000}
                placeholder={l(
                  "A product photo on a light background",
                  "Foto de un producto sobre fondo claro",
                )}
              />
            </Field>
            {attempted && !file && (
              <p role="alert" className="text-xs text-destructive-foreground">
                {l(
                  "Choose a file to continue.",
                  "Elige un archivo para continuar.",
                )}
              </p>
            )}
            {session.write.pending && (
              <div
                role="progressbar"
                aria-label={l(
                  "Uploading; byte progress is unavailable",
                  "Subiendo; el progreso de bytes no está disponible",
                )}
                aria-valuetext={l(
                  "Waiting for the upload response",
                  "Esperando la respuesta de subida",
                )}
                className="overflow-hidden rounded-full bg-surface-subtle"
              >
                <div className="h-1.5 w-full bg-primary/35 motion-safe:animate-pulse motion-reduce:animate-none" />
              </div>
            )}
            <OperationalPermissionNote action={uploadAction} />
            <div className="flex flex-wrap gap-2">
              <Button
                type="submit"
                appearance="gradient"
                loading={session.write.pending}
                disabled={
                  !canUpload ||
                  session.read.pending ||
                  (uploadedFile === file && Boolean(file))
                }
              >
                <Upload aria-hidden="true" />
                {uploadedFile === file && file
                  ? l("Upload confirmed", "Subida confirmada")
                  : session.write.error &&
                      session.write.errorCode !== "cancelled"
                    ? l("Retry upload", "Reintentar subida")
                    : l("Upload file", "Subir archivo")}
              </Button>
              {file && (
                <Button
                  type="button"
                  variant="ghost"
                  disabled={busy}
                  onClick={() => {
                    choose(null);
                    if (picker.current) picker.current.value = "";
                  }}
                >
                  <X aria-hidden="true" />
                  {l("Clear", "Limpiar")}
                </Button>
              )}
            </div>
          </form>
        </OperationalPanel>
        <OperationalPanel
          title={l("File preview", "Vista previa del archivo")}
          description={l(
            "The selected preview stays on this device until you upload.",
            "La vista seleccionada queda en este dispositivo hasta que la subas.",
          )}
        >
          {file ? (
            <div className="space-y-4">
              <div className="flex min-h-52 items-center justify-center overflow-hidden rounded-xl border border-border bg-surface-subtle/50">
                {preview ? (
                  <img
                    src={preview}
                    alt={
                      alt.trim() ||
                      l(
                        "Selected image preview",
                        "Vista previa de la imagen seleccionada",
                      )
                    }
                    className="max-h-72 max-w-full object-contain"
                  />
                ) : (
                  <File
                    className="size-12 text-muted-foreground"
                    aria-hidden="true"
                  />
                )}
              </div>
              <dl className="grid gap-3 text-xs sm:grid-cols-2">
                <div>
                  <dt className="text-muted-foreground">
                    {l("Filename", "Nombre")}
                  </dt>
                  <dd className="mt-1 break-all font-medium">
                    {operationalText(file.name, 200)}
                  </dd>
                </div>
                <div>
                  <dt className="text-muted-foreground">
                    {l("Size", "Tamaño")}
                  </dt>
                  <dd className="mt-1 font-medium">
                    {number(file.size / 1024, { maximumFractionDigits: 1 })} KB
                  </dd>
                </div>
                <div className="sm:col-span-2">
                  <dt className="text-muted-foreground">
                    {l("Description", "Descripción")}
                  </dt>
                  <dd className="mt-1 break-words leading-6">
                    {operationalText(alt, 1000) ||
                      l(
                        "Add a description in the upload form.",
                        "Añade una descripción en el formulario de subida.",
                      )}
                  </dd>
                </div>
              </dl>
            </div>
          ) : (
            <OperationalEmpty>
              <ImagePlus
                className="mx-auto mb-3 size-8 text-muted-foreground"
                aria-hidden="true"
              />
              {l(
                "Choose a file to inspect its size and preview.",
                "Elige un archivo para revisar su tamaño y vista previa.",
              )}
            </OperationalEmpty>
          )}
        </OperationalPanel>
      </div>
      {session.snapshot.uploads.length > 0 && (
        <OperationalPanel title={l("Confirmed uploads", "Subidas confirmadas")}>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {session.snapshot.uploads.map((asset) => (
              <OperationalUpload key={asset.id} asset={asset} />
            ))}
          </div>
        </OperationalPanel>
      )}
      <OperationalPanel
        title={l("File library", "Biblioteca de archivos")}
        accessory={<OperationalRefresh session={session} />}
      >
        <OperationalRecordTable
          records={session.snapshot.records}
          total={session.total}
          loading={session.read.pending}
          error={session.read.error}
          onRetry={() => void session.refresh()}
          onSelect={setDetail}
        />
        {detail && (
          <div className="mt-4">
            <OperationalRecordDetail
              record={
                session.snapshot.records.find(
                  (item) => item.id === detail.id,
                ) ?? detail
              }
            />
          </div>
        )}
      </OperationalPanel>
    </div>
  );
}

function OperationalEmailDelivery({
  delivery,
  demo,
}: {
  delivery: Extract<IntegrationResult, { kind: "delivery" }>["delivery"];
  demo: boolean;
}) {
  const { l } = useLanguage();
  const presentation = operationalEmailStatus(delivery.status);
  const details = reportedEmailDetails(delivery);
  return (
    <article className="space-y-3 rounded-xl border border-border bg-surface-subtle/40 p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="flex min-w-0 items-center gap-2 text-xs font-semibold">
          <Mail className="size-4 shrink-0 text-primary" aria-hidden="true" />
          <span className="break-all">
            {operationalText(delivery.recipient, 200)}
          </span>
        </p>
        <Badge variant={presentation.variant} appearance="soft">
          {l(...presentation.label)}
        </Badge>
      </div>
      <h4 className="break-words text-sm font-semibold">
        {operationalText(delivery.subject, 300)}
      </h4>
      <p className="whitespace-pre-wrap break-words text-xs leading-6">
        {operationalText(delivery.preview, 3000)}
      </p>
      <dl className="grid gap-3 border-t border-border pt-3 text-xs sm:grid-cols-2">
        <div className="min-w-0">
          <dt className="text-[11px] text-muted-foreground">
            {l("Reported reason code", "Código de motivo reportado")}
          </dt>
          <dd className="mt-1 break-words">
            {details.reasonCode
              ? operationalText(details.reasonCode, 300)
              : l("Not reported", "No reportado")}
          </dd>
        </div>
        <div className="min-w-0">
          <dt className="text-[11px] text-muted-foreground">
            {l("Provider event time", "Hora del evento del proveedor")}
          </dt>
          <dd className="mt-1">
            {details.occurredAt ? (
              <OperationalDate value={details.occurredAt} />
            ) : (
              l("Not reported", "No reportada")
            )}
          </dd>
        </div>
      </dl>
      <p className="text-[11px] text-muted-foreground">
        {demo
          ? l(
              "Demo status; no email was sent externally.",
              "Estado demo; no se envió un correo externo.",
            )
          : l(
              "Delivery status reported by the connected backend.",
              "Estado de entrega reportado por el backend conectado.",
            )}
      </p>
    </article>
  );
}

export function OperationalEmail({
  props,
  session,
  stage,
}: OperationalDomainProps) {
  const { l } = useLanguage();
  const send = operationalAction(props.definition, "send-email");
  const [values, setValues] = useState(() => initialOperationalValues(send));
  const [template, setTemplate] = useState("custom");
  const [variables, setVariables] = useState<Record<string, string>>({});
  const [attempted, setAttempted] = useState(false);
  const [detail, setDetail] = useState<IntegrationRecord | null>(null);
  const subject = operationalValue(send, values, "subject");
  const body = operationalValue(send, values, "content");
  const recipient = operationalValue(send, values, "recipient");
  const variableNames = operationalTemplateVariables(subject, body);
  const renderedSubject = interpolateOperationalTemplate(subject, variables);
  const renderedBody = interpolateOperationalTemplate(body, variables);
  const missing = [
    ...new Set([...renderedSubject.missing, ...renderedBody.missing]),
  ];
  const variableField = operationalField(send, "variables");
  const recipientField = operationalField(send, "recipient");
  const multipleRecipients =
    recipientField &&
    /recipients|addresses|list/i.test(
      `${recipientField.id} ${recipientField.label.en}`,
    );
  let prepared = withOperationalValue(
    send,
    values,
    "subject",
    renderedSubject.text,
  );
  prepared = withOperationalValue(send, prepared, "content", renderedBody.text);
  if (variableField?.type === "text")
    prepared = {
      ...prepared,
      [variableField.id]: JSON.stringify(
        Object.fromEntries(
          variableNames.map((name) => [name, variables[name] ?? ""]),
        ),
      ),
    };
  const recipientInvalid =
    recipientField?.type === "text" &&
    !validOperationalRecipients(recipient, multipleRecipients ? 100 : 1);
  const errors = send ? validateOperationalValues(send, prepared) : {};
  const busy = session.write.pending || session.read.pending;
  const templates = {
    welcome: {
      subject: l("Welcome, {{name}}", "Te damos la bienvenida, {{name}}"),
      body: l(
        "Hi {{name}},\n\nYour {{workspace}} workspace is ready. You can open it here:\n{{url}}\n\nWelcome aboard.",
        "Hola, {{name}}:\n\nTu espacio {{workspace}} está listo. Puedes abrirlo aquí:\n{{url}}\n\nTe damos la bienvenida.",
      ),
    },
    digest: {
      subject: l(
        "Your {{workspace}} weekly update",
        "Tu resumen semanal de {{workspace}}",
      ),
      body: l(
        "Hi {{name}},\n\nHere is this week’s update:\n{{summary}}\n\nSee the full activity at {{url}}.",
        "Hola, {{name}}:\n\nEste es el resumen de la semana:\n{{summary}}\n\nRevisa toda la actividad en {{url}}.",
      ),
    },
    update: {
      subject: l(
        "An update about {{project}}",
        "Una actualización sobre {{project}}",
      ),
      body: l(
        "Hi {{name}},\n\n{{message}}\n\nThanks,\n{{team}}",
        "Hola, {{name}}:\n\n{{message}}\n\nGracias,\n{{team}}",
      ),
    },
  };
  return (
    <div className="space-y-5">
      <div className="grid gap-5 xl:grid-cols-2">
        <OperationalPanel
          title={l("Compose an email", "Redactar un correo")}
          description={l(
            "Draft, fill the variables and review the final message before sending.",
            "Redacta, completa las variables y revisa el mensaje final antes de enviarlo.",
          )}
        >
          {!send ? (
            <OperationalEmpty>
              {l(
                "This connection does not expose email sending.",
                "Esta conexión no ofrece envío de correo.",
              )}
            </OperationalEmpty>
          ) : (
            <form
              noValidate
              className="space-y-4"
              onSubmit={(event) => {
                event.preventDefault();
                setAttempted(true);
                if (
                  busy ||
                  !session.can(send) ||
                  Object.keys(errors).length ||
                  recipientInvalid ||
                  missing.length
                )
                  return;
                stage(send, prepared, {
                  review: true,
                  content: renderedBody.text,
                });
              }}
            >
              <Field
                label={l("Draft example", "Ejemplo de borrador")}
                description={l(
                  "Local starting points. Provider template choices remain in the fields below.",
                  "Puntos de partida locales. Las plantillas del proveedor siguen en los campos de abajo.",
                )}
              >
                <Select
                  value={template}
                  options={[
                    {
                      value: "custom",
                      label: l("Custom draft", "Borrador propio"),
                    },
                    { value: "welcome", label: l("Welcome", "Bienvenida") },
                    {
                      value: "digest",
                      label: l("Weekly digest", "Resumen semanal"),
                    },
                    {
                      value: "update",
                      label: l("Project update", "Actualización de proyecto"),
                    },
                  ]}
                  onValueChange={(value) => {
                    setTemplate(value);
                    setVariables({});
                    if (value !== "custom") {
                      const draft = templates[value as keyof typeof templates];
                      if (draft)
                        setValues(
                          withOperationalValue(
                            send,
                            withOperationalValue(
                              send,
                              values,
                              "subject",
                              draft.subject,
                            ),
                            "content",
                            draft.body,
                          ),
                        );
                    }
                  }}
                  disabled={busy}
                />
              </Field>
              <OperationalFields
                action={send}
                values={values}
                onChange={setValues}
                disabled={busy}
                errors={attempted ? errors : {}}
                exclude={
                  variableField?.type === "text" ? [variableField.id] : []
                }
              />
              {variableNames.length > 0 && (
                <fieldset className="space-y-3 rounded-xl border border-border bg-surface-subtle/40 p-4">
                  <legend className="px-1 text-xs font-semibold">
                    {l("Template variables", "Variables de plantilla")}
                  </legend>
                  <div className="grid gap-3 sm:grid-cols-2">
                    {variableNames.map((name) => (
                      <Field
                        key={name}
                        label={name}
                        error={
                          attempted && missing.includes(name)
                            ? l(
                                "Complete this variable.",
                                "Completa esta variable.",
                              )
                            : undefined
                        }
                      >
                        <Input
                          value={variables[name] ?? ""}
                          onChange={(event) =>
                            setVariables({
                              ...variables,
                              [name]: event.target.value,
                            })
                          }
                          disabled={busy}
                        />
                      </Field>
                    ))}
                  </div>
                </fieldset>
              )}
              {attempted && recipientInvalid && (
                <p role="alert" className="text-xs text-destructive-foreground">
                  {l(
                    "Enter a valid recipient email address.",
                    "Escribe un correo válido para el destinatario.",
                  )}
                </p>
              )}
              <OperationalPermissionNote action={send} />
              <Button
                type="submit"
                appearance="gradient"
                disabled={!session.can(send)}
                loading={busy}
              >
                <Mail aria-hidden="true" />
                {l("Review email", "Revisar correo")}
              </Button>
            </form>
          )}
        </OperationalPanel>
        <OperationalPanel
          title={l("Content preview", "Vista previa del contenido")}
          description={l(
            "Plain-text preview of the values that will be submitted.",
            "Vista en texto del contenido que se enviará.",
          )}
        >
          <article className="overflow-hidden rounded-xl border border-border">
            <dl className="space-y-3 border-b border-border bg-surface-subtle/50 p-4 text-xs">
              <div className="flex gap-3">
                <dt className="w-14 shrink-0 text-muted-foreground">
                  {l("To", "Para")}
                </dt>
                <dd className="break-all">
                  {operationalText(recipient, 500) ||
                    l("Add a recipient", "Añade un destinatario")}
                </dd>
              </div>
              <div className="flex gap-3">
                <dt className="w-14 shrink-0 text-muted-foreground">
                  {l("Subject", "Asunto")}
                </dt>
                <dd className="break-words font-semibold">
                  {operationalText(renderedSubject.text, 500) ||
                    l("Add a subject", "Añade un asunto")}
                </dd>
              </div>
            </dl>
            <div className="min-h-52 whitespace-pre-wrap break-words p-5 text-sm leading-7">
              {operationalText(renderedBody.text, 8000) ||
                l(
                  "Your message preview appears here.",
                  "La vista previa de tu mensaje aparece aquí.",
                )}
            </div>
          </article>
          {missing.length > 0 && (
            <p className="mt-3 text-xs leading-6 text-muted-foreground">
              {l("Variables still to fill:", "Variables por completar:")}{" "}
              {missing.map((name) => operationalText(name, 60)).join(", ")}
            </p>
          )}
        </OperationalPanel>
      </div>
      <OperationalPanel
        title={l("Delivery queue", "Cola de entrega")}
        description={l(
          "Statuses come from the backend. A queued response is not a delivery confirmation.",
          "Los estados vienen del backend. Una respuesta en cola no confirma la entrega.",
        )}
        accessory={<OperationalRefresh session={session} />}
      >
        {session.snapshot.deliveries.length ? (
          <div className="grid gap-4 lg:grid-cols-2">
            {[...session.snapshot.deliveries].reverse().map((delivery) => (
              <div key={delivery.id} className="space-y-2">
                <OperationalEmailDelivery
                  delivery={delivery}
                  demo={props.adapter.mode === "demo"}
                />
                {["failed", "rejected", "bounced"].includes(delivery.status) &&
                  send && (
                    <div className="space-y-2">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        disabled={busy || !session.can(send)}
                        onClick={() => {
                          let next = initialOperationalValues(send);
                          next = withOperationalValue(
                            send,
                            next,
                            "recipient",
                            delivery.recipient,
                          );
                          next = withOperationalValue(
                            send,
                            next,
                            "subject",
                            delivery.subject,
                          );
                          next = withOperationalValue(
                            send,
                            next,
                            "content",
                            delivery.preview,
                          );
                          setValues(next);
                          setTemplate("custom");
                          setVariables({});
                          setAttempted(false);
                        }}
                      >
                        {l(
                          "Edit a retry draft",
                          "Editar borrador para reintentar",
                        )}
                      </Button>
                      <p className="text-[11px] leading-5 text-muted-foreground">
                        {l(
                          "Review the recipient and reported cause before sending a new message. The backend owns suppression and retry policy.",
                          "Revisa el destinatario y el motivo reportado antes de enviar otro mensaje. El backend controla la supresión y la política de reintentos.",
                        )}
                      </p>
                    </div>
                  )}
              </div>
            ))}
          </div>
        ) : (
          <OperationalEmpty>
            {l(
              "No email responses in this session yet.",
              "Aún no hay respuestas de correo en esta sesión.",
            )}
          </OperationalEmpty>
        )}
        <div className="mt-5">
          <OperationalRecordTable
            records={session.snapshot.records}
            total={session.total}
            loading={session.read.pending}
            error={session.read.error}
            onRetry={() => void session.refresh()}
            onSelect={setDetail}
          />
        </div>
        {detail && (
          <div className="mt-4">
            <OperationalRecordDetail
              record={
                session.snapshot.records.find(
                  (record) => record.id === detail.id,
                ) ?? detail
              }
            />
          </div>
        )}
      </OperationalPanel>
    </div>
  );
}

