function OperationalHits({ hits }: { hits: IntegrationSearchHit[] }) {
  const { l } = useLanguage();
  if (!hits.length)
    return (
      <OperationalEmpty>
        {l("No matches returned.", "No se devolvieron coincidencias.")}
      </OperationalEmpty>
    );
  return (
    <div className="grid gap-3">
      {hits.map((hit) => {
        const url = operationalPublicUrl(hit.url);
        return (
          <article
            key={hit.id}
            className="rounded-xl border border-border bg-surface-subtle/40 p-4"
          >
            <h4 className="text-sm font-semibold">
              {operationalText(hit.title, 200)}
            </h4>
            <p className="mt-2 whitespace-pre-wrap break-words text-xs leading-6">
              {operationalText(hit.snippet, 1600)}
            </p>
            <p className="mt-3 text-[11px] text-muted-foreground">
              {operationalText(hit.source, 150)}
            </p>
            {url && (
              <a
                href={url}
                target="_blank"
                rel="noopener noreferrer"
                className="af-hover-link mt-2 inline-flex min-h-9 items-center gap-1 text-xs text-primary"
              >
                {l("Open source", "Abrir fuente")}
                <ArrowUpRight className="size-3.5" aria-hidden="true" />
              </a>
            )}
          </article>
        );
      })}
    </div>
  );
}

/** Result kind, rather than the requested family, controls response presentation. */
export function OperationalResult({
  result,
  demo,
  className,
}: {
  result: IntegrationResult | null;
  demo?: boolean;
  className?: string;
}) {
  const { l, number } = useLanguage();
  if (!result)
    return (
      <OperationalEmpty>
        {l(
          "Run an action to see its backend response.",
          "Ejecuta una acción para ver la respuesta del backend.",
        )}
      </OperationalEmpty>
    );
  let content: React.ReactNode;
  switch (result.kind) {
    case "records":
      content = (
        <OperationalRecordTable records={result.records} total={result.total} />
      );
      break;
    case "record":
      content = <OperationalRecordDetail record={result.record} />;
      break;
    case "upload":
      content = <OperationalUpload asset={result.asset} />;
      break;
    case "delivery":
      content = <OperationalDelivery delivery={result.delivery} demo={demo} />;
      break;
    case "metrics":
      content = (
        <div className="space-y-5">
          <OperationalMetrics metrics={result.metrics} />
          <OperationalRecordTable
            records={result.events}
            title={l("Events", "Eventos")}
          />
        </div>
      );
      break;
    case "job":
      content = <OperationalJob job={result.job} />;
      break;
    case "document":
      content = (
        <article className="rounded-xl border border-border p-4">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h4 className="text-sm font-semibold">
              {operationalText(result.document.title, 200)}
            </h4>
            <Badge variant="neutral">
              {result.document.format} · {l("Revision", "Revisión")}{" "}
              {number(result.document.revision)}
            </Badge>
          </div>
          <p className="mt-2 text-xs text-muted-foreground">
            <OperationalDate value={result.document.updatedAt} />
          </p>
          <div
            className={cn(
              "mt-4 max-h-72 overflow-auto whitespace-pre-wrap break-words text-xs leading-7",
              result.document.format === "json" && "font-mono",
            )}
          >
            {operationalText(result.document.content, 12000)}
          </div>
        </article>
      );
      break;
    case "search":
      content = <OperationalHits hits={result.hits} />;
      break;
    case "map":
      content = result.locations.length ? (
        <div className="grid gap-3">
          {result.locations.map((location) => (
            <article
              key={location.id}
              className="rounded-xl border border-border p-4"
            >
              <h4 className="text-sm font-semibold">
                {operationalText(location.name, 200)}
              </h4>
              <p className="mt-2 text-xs text-muted-foreground">
                {l("Latitude", "Latitud")}:{" "}
                {number(location.latitude, { maximumFractionDigits: 6 })} ·{" "}
                {l("Longitude", "Longitud")}:{" "}
                {number(location.longitude, { maximumFractionDigits: 6 })}
              </p>
            </article>
          ))}
        </div>
      ) : (
        <OperationalEmpty>
          {l("No locations returned.", "No se devolvieron ubicaciones.")}
        </OperationalEmpty>
      );
      break;
    case "knowledge":
      content = (
        <div className="space-y-4">
          <OperationalStatus value={result.status} />
          <OperationalRecordTable
            records={result.documents}
            title={l("Documents", "Documentos")}
          />
          <OperationalHits hits={result.hits} />
        </div>
      );
      break;
    case "tool":
      content = (
        <article className="space-y-4 rounded-xl border border-border p-4">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h4 className="text-sm font-semibold">
              {operationalText(result.run.name, 200)}
            </h4>
            <OperationalStatus value={result.run.state} />
          </div>
          <dl className="grid gap-3">
            {Object.entries(result.run.input)
              .filter(([key]) => !operationalSensitiveField(key))
              .map(([key, value]) => (
                <div key={key}>
                  <dt className="text-[11px] text-muted-foreground">
                    {operationalText(key, 80)}
                  </dt>
                  <dd className="mt-1 whitespace-pre-wrap break-words text-xs leading-6">
                    {operationalText(value, 1200)}
                  </dd>
                </div>
              ))}
          </dl>
          {result.run.output && (
            <p className="whitespace-pre-wrap break-words text-xs leading-6">
              {operationalText(result.run.output, 4000)}
            </p>
          )}
          {result.run.state === "approval-required" && (
            <p className="text-xs text-muted-foreground">
              {l(
                "The backend requires a separate tool approval.",
                "El backend requiere una aprobación de herramienta separada.",
              )}
            </p>
          )}
        </article>
      );
      break;
    case "receipt":
      content = (
        <div
          role="status"
          className="flex items-start gap-3 rounded-xl border border-primary/20 bg-accent/40 p-4"
        >
          <CheckCircle2
            className="mt-0.5 size-4 shrink-0 text-primary"
            aria-hidden="true"
          />
          <p className="whitespace-pre-wrap break-words text-xs leading-6">
            {operationalText(result.message, 2000) ||
              l(
                "Backend response received.",
                "Se recibió la respuesta del backend.",
              )}
          </p>
        </div>
      );
      break;
  }
  return <div className={className}>{content}</div>;
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { useIntegrationOperation } from "@/hooks/use-integration-operation";
import type {
  IntegrationAction,
  IntegrationResult,
  IntegrationValues,
  IntegrationWorkbenchProps,
} from "@/lib/integrations/contracts";
import {
  emptyOperationalSnapshot,
  mergeOperationalResult,
  operationalDefaultQuery,
  operationalPayload,
  operationalPermitted,
  scopedOperationalValues,
  validateOperationalValues,
} from "./operational-model";

export type OperationalHistoryEntry = {
  sequence: number;
  action: IntegrationAction;
  values: IntegrationValues;
  result: IntegrationResult;
  receivedAt: string;
};

/** Read and mutation channels keep a refresh from replacing an action receipt. */
export function useOperationalSession(props: IntegrationWorkbenchProps) {
  const read = useIntegrationOperation(props);
  const write = useIntegrationOperation(props);
  const { run: readRun, reset: readReset } = read;
  const { run: writeRun, upload: writeUpload, reset: writeReset } = write;
  const [snapshot, setSnapshot] = useState(emptyOperationalSnapshot);
  const [history, setHistory] = useState<OperationalHistoryEntry[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [total, setTotal] = useState<number | null>(null);
  const [queryId, setQueryId] = useState(
    () =>
      operationalDefaultQuery(
        props.definition,
        props.connection.resourceIds,
        props.connection.grantedPermissions,
      )?.id,
  );
  const historySequence = useRef(0);
  const queryInputs = useRef(new Map<string, IntegrationValues>());
  const generation = useRef(0);
  const mounted = useRef(false);
  const context = useRef(props);
  useLayoutEffect(() => {
    context.current = props;
  }, [props]);
  const queries = props.definition.actions.filter(
    (action) => action.kind === "query",
  );
  const query =
    queries.find((action) => action.id === queryId) ??
    operationalDefaultQuery(
      props.definition,
      props.connection.resourceIds,
      props.connection.grantedPermissions,
    );
  const connected =
    props.connection.status === "connected" && !props.scope.signal?.aborted;
  const can = (action: IntegrationAction | null) =>
    connected &&
    operationalPermitted(action, props.connection.grantedPermissions);

  const accept = useCallback((result: IntegrationResult, replace: boolean) => {
    setSnapshot((previous) =>
      mergeOperationalResult(previous, result, replace),
    );
    if (replace) {
      setLoaded(true);
      setTotal(result.kind === "records" ? result.total : null);
    }
  }, []);

  const runRead = useCallback(
    async (action: IntegrationAction, values: IntegrationValues = {}) => {
      const ticket = generation.current;
      const adapter = props.adapter;
      const result = await readRun(action, operationalPayload(action, values));
      if (
        !result ||
        !mounted.current ||
        ticket !== generation.current ||
        context.current.adapter !== adapter ||
        context.current.scope.signal?.aborted
      )
        return null;
      accept(result, true);
      return result;
    },
    [accept, props.adapter, readRun],
  );

  const refresh = useCallback(
    async (values?: IntegrationValues) => {
      if (!query) return null;
      const input =
        values ??
        queryInputs.current.get(query.id) ??
        scopedOperationalValues(query, props.connection.resourceIds);
      if (Object.keys(validateOperationalValues(query, input)).length)
        return null;
      queryInputs.current.set(
        query.id,
        Object.fromEntries(
          Object.entries(input).map(([key, value]) => [
            key,
            Array.isArray(value) ? [...value] : value,
          ]),
        ),
      );
      return runRead(query, input);
    },
    [props.connection.resourceIds, query, runRead],
  );

  const run = useCallback(
    async (action: IntegrationAction, values: IntegrationValues = {}) => {
      const ticket = generation.current;
      const adapter = props.adapter;
      const input = operationalPayload(action, values);
      const result = await writeRun(action, input);
      if (
        !result ||
        !mounted.current ||
        ticket !== generation.current ||
        context.current.adapter !== adapter ||
        context.current.scope.signal?.aborted
      )
        return null;
      accept(result, false);
      const entry: OperationalHistoryEntry = {
        sequence: ++historySequence.current,
        action,
        values: input,
        result,
        receivedAt: new Date().toISOString(),
      };
      setHistory((previous) => [entry, ...previous].slice(0, 20));
      return result;
    },
    [accept, props.adapter, writeRun],
  );

  const upload = useCallback(
    async (file: File, alt?: string) => {
      const ticket = generation.current;
      const adapter = props.adapter;
      const result = await writeUpload(file, alt);
      if (
        !result ||
        !mounted.current ||
        ticket !== generation.current ||
        context.current.adapter !== adapter ||
        context.current.scope.signal?.aborted
      )
        return null;
      accept(result, false);
      return result;
    },
    [accept, props.adapter, writeUpload],
  );

  // Adapter replacement is also a scope change, even when connection IDs match.
  useEffect(() => {
    mounted.current = true;
    generation.current += 1;
    setSnapshot(emptyOperationalSnapshot());
    setHistory([]);
    setLoaded(false);
    setTotal(null);
    queryInputs.current.clear();
    readReset();
    writeReset();
    return () => {
      mounted.current = false;
      generation.current += 1;
      readReset();
      writeReset();
    };
  }, [props.adapter, readReset, writeReset]);

  useEffect(() => {
    if (connected && !props.scope.signal?.aborted) void refresh();
  }, [connected, props.adapter, props.scope.signal, refresh]);

  return {
    read,
    write,
    run,
    upload,
    refresh,
    runRead,
    query,
    queries,
    setQueryId,
    can,
    initialQueryValues: scopedOperationalValues(
      query,
      props.connection.resourceIds,
    ),
    snapshot,
    history,
    loaded,
    total,
    connected,
  };
}

